const p = 0.999;
const minutesPerYear = 525600;
function line(n) {
  const a = Math.pow(p, n);
  const downtimeMin = (1 - a) * minutesPerYear;
  return `N=${String(n).padStart(2)}  avail=${(a * 100).toFixed(4)}%  downtime=${downtimeMin.toFixed(0)} min/yr`;
}
for (const n of [1, 5, 10, 30]) console.log(line(n));
// A cache serving 20 of the 30 deps from memory removes them from the hot path.
const withCache = Math.pow(p, 10);
console.log(`cache cuts chain 30->10  avail=${(withCache * 100).toFixed(4)}%`);
